"""Experimental native fixed-radius S-to-circle contact family.

Moves one contact station and solves the other on its original curb. Both
arcs keep the requested radius. The ordinary circle is the zero-length limit
of one arc. Bracket discovery is sampled and retains ambiguous results; this
primitive does not qualify a complete perimeter, surface or edit policy.
"""
import math

import bpy

from . import curved_corner_nodes as c


def build(*, polyline=False):
    name = 'Prochitecture Streets / Fixed-radius contact transition v2'
    if polyline:
        name += ' / Exact or smooth paths'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    for side in ('A', 'B'):
        g.socket('Path '+side, 'NodeSocketGeometry')
        g.socket('Width '+side, 'NodeSocketFloat', default=6.)
        g.socket('Offset '+side, 'NodeSocketFloat', default=0.)
    for key in ('Circle', 'Local'):
        g.socket(key, 'NodeSocketGeometry')
    g.socket('Radius', 'NodeSocketFloat', default=2.)
    g.socket('Circle Weight', 'NodeSocketFloat', default=.5)
    g.socket('Input Valid', 'NodeSocketBool', default=False)
    g.socket('Candidates', 'NodeSocketGeometry', 'OUTPUT')
    g.socket('Candidate Count', 'NodeSocketInt', 'OUTPUT')
    g.socket('Diagnostics', 'NodeSocketGeometry', 'OUTPUT')
    inp = g.node('NodeGroupInput')
    circle, local = [inp.outputs[key] for key in ('Circle', 'Local')]
    radius = c.V(g, inp.outputs['Radius'])
    weight = c.bounded(g, inp.outputs['Circle Weight'])
    paths = [inp.outputs['Path '+side] for side in ('A', 'B')]
    offsets = [c.V(g, inp.outputs['Offset '+side])+sign*.5*c.V(g, inp.outputs['Width '+side])
               for side, sign in (('A', -1.), ('B', 1.))]
    sign = g.math('SIGN', c._read(g, local, 'st_cc_sweep', 0))
    anchor_a = g.math('LESS_THAN', sign*c._read(g, circle, 'st_cc_sweep', 0), 0.)
    local_s = [c._read(g, local, 'st_cc_s'+side, 0) for side in ('a', 'b')]
    circle_s = [c._read(g, circle, 'st_cc_s'+side, 0) for side in ('a', 'b')]
    mixed = [(1.-weight)*a+weight*b for a, b in zip(local_s, circle_s)]
    anchor = c.choose(g, anchor_a, mixed[0], mixed[1])
    other_path = c.choose(g, anchor_a, paths[1], paths[0], 'GEOMETRY')
    other_offset = c.choose(g, anchor_a, offsets[1], offsets[0])
    first = c.choose(g, anchor_a, local_s[1], local_s[0])
    last = c.choose(g, anchor_a, circle_s[1], circle_s[0])
    lower, upper = g.math('MINIMUM', first, last), g.math('MAXIMUM', first, last)
    def center(path, parameter, curb):
        return c._circle_jet(g, path, parameter, curb+sign*radius, polyline=polyline,
                             curb_offset=curb, radius_offset=sign*radius)
    centers = [c._vec(g, center(path, anchor, offset)['Center']) for path, offset in zip(paths, offsets)]
    fixed = c._pick(g, anchor_a, centers[0], centers[1])
    def residual(parameter):
        delta = c._sub(c._vec(g, center(other_path, parameter, other_offset)['Center']), fixed)
        return c._dot(delta, delta)-4.*radius*radius
    valid = c.V(g, inp.outputs['Input Valid'])*g.math('GREATER_THAN', radius, 1e-5)
    valid = valid*g.math('LESS_THAN', radius, 1e5)
    ready = valid*g.math('COMPARE', c._count(g, circle), 1.)*g.math('COMPARE', c._count(g, local), 1.)
    ready = ready*g.math('COMPARE', c._read(g, local, 'st_ct_kind', 0, 'INT'), 2.)
    ready = ready*g.math('GREATER_THAN', weight, 0.)*g.math('LESS_THAN', weight, 1.)
    # Established contacts are float-valued roots. Near the circle limit their
    # roundoff can put the true root just outside the nominal interval. Expand
    # discovery by the existing corner solver tolerance, retaining its domain
    # and all final physical residual limits. This changes search, not acceptance.
    length = c._read(g, other_path, 'st_cc_knot', c._count(g, other_path)-1.)
    domain_min = -4.*(g.math('MAXIMUM', inp.outputs['Width A'], inp.outputs['Width B'])+2.*radius)
    search_lo = g.math('MAXIMUM', lower-c.TOLERANCE, domain_min)
    search_hi = g.math('MINIMUM', upper+c.TOLERANCE, length)
    # Include authored knots: a bracket must not skip a polynomial boundary.
    samples = c._samples(g, other_path, search_hi, search_lo, other_offset+sign*radius, g.math('ADD', 16., 0.),
                         polyline=polyline, curb_offset=other_offset, radius_offset=sign*radius)
    parameter = c.named(g, 'st_cc_sample_s')
    samples = c._select(g, samples, (1.-g.math('LESS_THAN', parameter, search_lo))*
                         (1.-g.math('GREATER_THAN', parameter, search_hi)))
    index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    lo = c._read(g, samples, 'st_cc_sample_s', index)
    hi = c._read(g, samples, 'st_cc_sample_s', index+1.)
    flo, fhi = residual(lo), residual(hi)
    hit = ready*g.math('LESS_THAN', index, c._count(g, samples)-1.)
    hit = hit*(1.-g.math('GREATER_THAN', flo*fhi, 0.))*g.math('GREATER_THAN', hi-lo, 1e-7)
    seeds = samples
    for key, value in (('lo', lo), ('hi', hi), ('flo', flo), ('hit', hit)):
        seeds = c._store(g, seeds, '_cx_'+key, value)
    seeds = c._select(g, seeds, c.named(g, '_cx_hit'))
    # Nearly identical established contacts can collapse in the seed merge or
    # float arithmetic. Their interpolated station is a bounded local guess,
    # still subject to the same radius and sweep checks below.
    collapsed = g.math('LESS_THAN', upper-lower, 1e-5)
    short_station = c.choose(g, anchor_a, mixed[1], mixed[0])
    short_seed = c._line(g, 1)
    for key, value in (('lo', short_station), ('hi', short_station), ('flo', residual(short_station))):
        short_seed = c._store(g, short_seed, '_cx_'+key, value)
    short_seed = c._select(g, short_seed, ready)
    seeds = c.choose(g, collapsed, short_seed, seeds, 'GEOMETRY')
    ri = g.node('GeometryNodeRepeatInput', 'Refine the opposite contact on its original curb')
    ro = g.node('GeometryNodeRepeatOutput')
    ri.pair_with_output(ro)
    ri.inputs['Iterations'].default_value = 28
    g.bind(seeds, ri.inputs['Geometry'])
    lo, hi, flo = [c.named(g, '_cx_'+key) for key in ('lo', 'hi', 'flo')]
    midpoint = (lo+hi)*.5
    fm = residual(midpoint)
    right = g.math('GREATER_THAN', flo*fm, 0.)
    geo = ri.outputs['Geometry']
    for key, value in (('next_lo', c.choose(g, right, midpoint, lo)),
                       ('next_hi', c.choose(g, right, hi, midpoint)),
                       ('next_flo', c.choose(g, right, fm, flo))):
        geo = c._store(g, geo, '_cx_'+key, value)
    for key in ('lo', 'hi', 'flo'):
        geo = c._store(g, geo, '_cx_'+key, c.named(g, '_cx_next_'+key))
    g.bind(geo, ro.inputs['Geometry'])
    other = (c.named(g, '_cx_lo')+c.named(g, '_cx_hi'))*.5
    stations = [c.choose(g, anchor_a, anchor, other), c.choose(g, anchor_a, other, anchor)]
    points = [c._vec(g, c._jet(g, p, s, d, polyline=polyline)['Center'])
              for p, s, d in zip(paths, stations, offsets)]
    centers = [c._vec(g, center(p, s, d)['Center']) for p, s, d in zip(paths, stations, offsets)]
    pa, pb = points
    ca, cb = centers
    joint = c._scale(c._add(ca, cb), .5)
    va, vj, vk, vb = c._sub(pa, ca), c._sub(joint, ca), c._sub(joint, cb), c._sub(pb, cb)
    wa = g.math('ARCTAN2', c._cross(va, vj), c._dot(va, vj))
    wb = g.math('ARCTAN2', c._cross(vk, vb), c._dot(vk, vb))
    error = g.math('ABSOLUTE', c._length(g, c._sub(cb, ca))-2.*radius)
    good = ready*g.math('LESS_THAN', error, 2e-5)
    good = good*g.math('GREATER_THAN', sign*wa, -1e-6)*g.math('GREATER_THAN', -sign*wb, -1e-6)
    for sweep in (wa, wb):
        good = good*g.math('LESS_THAN', g.math('ABSOLUTE', sweep), math.pi-1e-5)
    # The contact root admits at most 1e-6 radians of signed roundoff above.
    # A nearly vanished arc can consequently have a wrong-sign atan2 result.
    # Preserve the known opposite turning directions; otherwise that tiny arc
    # reverses its unit tangent and folds an entire profile band. The analytic
    # radius is unchanged, and independent contact/arc checks remain required.
    wa=sign*g.math('ABSOLUTE',wa)
    wb=-sign*g.math('ABSOLUTE',wb)
    geo = ro.outputs['Geometry']
    for key, value, kind in (
        ('st_ct_kind', 2, 'INT'), ('st_cc_sa', stations[0], 'FLOAT'), ('st_cc_sb', stations[1], 'FLOAT'),
        ('st_cc_radius', radius, 'FLOAT'), ('st_cc_contact_a', g.xyz(*pa), 'FLOAT_VECTOR'),
        ('st_cc_contact_b', g.xyz(*pb), 'FLOAT_VECTOR'), ('st_cc_center', g.xyz(*ca), 'FLOAT_VECTOR'),
        ('st_ct_second_center', g.xyz(*cb), 'FLOAT_VECTOR'), ('st_ct_join', g.xyz(*joint), 'FLOAT_VECTOR'),
        ('st_cc_sweep', wa, 'FLOAT'), ('st_ct_sweep_b', wb, 'FLOAT'), ('st_cc_residual', error, 'FLOAT'),
        ('st_cx_roundoff_interval', collapsed, 'BOOLEAN'),
        ('_cx_good', good, 'BOOLEAN')):
        geo = c._store(g, geo, key, value, kind)
    geo = c._select(g, geo, c.named(g, '_cx_good', 'BOOLEAN'))
    geo = g.setpos(geo, g.xyz(c.named(g, 'st_cc_sa'), c.named(g, 'st_cc_sb')))
    merge = g.node('GeometryNodeMergeByDistance', 'Deduplicate identical contact roots')
    merge.inputs['Distance'].default_value = 1e-4
    g.bind(geo, merge.inputs['Geometry'])
    result = c.choose(g, g.math('LESS_THAN', weight, 1.), merge.outputs['Geometry'], circle, 'GEOMETRY')
    result = c.choose(g, g.math('GREATER_THAN', weight, 0.), result, local, 'GEOMETRY')
    result = c._select(g, result, valid)
    out = g.node('NodeGroupOutput')
    g.bind(result, out.inputs['Candidates'])
    g.bind(c._count(g, result), out.inputs['Candidate Count'])
    diagnostic = c._line(g, 1)
    for key, value in (('ready', ready), ('circle_count', c._count(g, circle)),
                       ('local_count', c._count(g, local)), ('anchor_a', anchor_a),
                       ('lower', lower), ('upper', upper), ('anchor', anchor),
                       ('search_lo', search_lo), ('search_hi', search_hi),
                       ('weight', weight), ('f_lower', residual(lower)), ('f_upper', residual(upper)),
                       ('seeds', c._count(g, seeds)), ('refined', c._count(g, ro.outputs['Geometry'])),
                       ('accepted', c._count(g, result))):
        diagnostic = c._store(g, diagnostic, 'st_cx_'+key, value)
    g.bind(diagnostic, out.inputs['Diagnostics'])
    return g.g
